using System.Drawing.Printing;
using HammerTrackPro2.Models;

namespace HammerTrackPro2.Services;

public sealed class BidderCardPrinter
{
    internal const string FontFamilyName="Arial Black";
    public PrintDocument CreateDocument(int bidderNumber,Auction auction){if(bidderNumber<=0)throw new ArgumentOutOfRangeException(nameof(bidderNumber),"Bidder number must be greater than zero.");ArgumentNullException.ThrowIfNull(auction);var document=new PrintDocument{DocumentName=$"Bidder Card {bidderNumber}"};document.DefaultPageSettings.Landscape=false;document.DefaultPageSettings.Margins=new Margins(35,35,35,35);document.PrintPage+=(_,e)=>Draw(e.Graphics??throw new InvalidOperationException("The printer did not provide a drawing surface."),e.MarginBounds,bidderNumber,auction.CompanyDisplayName);return document;}
    internal static void Draw(Graphics graphics,Rectangle bounds,int bidderNumber,string auctionHouse){if(bidderNumber<=0)throw new ArgumentOutOfRangeException(nameof(bidderNumber));var numberText=bidderNumber.ToString();var numberArea=new RectangleF(bounds.Left,bounds.Top,bounds.Width,bounds.Height*0.69F);using var numberFont=CreateFittedFont(graphics,numberText,numberArea,310F,FontStyle.Bold);using var centered=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center,FormatFlags=StringFormatFlags.NoWrap};graphics.DrawString(numberText,numberFont,Brushes.Black,numberArea,centered);var dividerY=bounds.Top+(int)(bounds.Height*0.73F);using var divider=new Pen(Color.Black,14F){StartCap=System.Drawing.Drawing2D.LineCap.Square,EndCap=System.Drawing.Drawing2D.LineCap.Square};graphics.DrawLine(divider,bounds.Left+12,dividerY,bounds.Right-12,dividerY);var company=string.IsNullOrWhiteSpace(auctionHouse)?"Auction House":auctionHouse.Trim();var companyArea=new RectangleF(bounds.Left+12,dividerY+24,bounds.Width-24,bounds.Bottom-dividerY-28);using var companyFont=CreateFittedFont(graphics,company.ToUpperInvariant(),companyArea,48F,FontStyle.Bold);graphics.DrawString(company.ToUpperInvariant(),companyFont,Brushes.Black,companyArea,centered);}
    internal static Font CreateFittedFont(Graphics graphics,string text,RectangleF area,float maximumSize,FontStyle style){for(var size=maximumSize;size>=16F;size-=2F){var font=new Font(FontFamilyName,size,style,GraphicsUnit.Point);var measured=graphics.MeasureString(text,font,int.MaxValue,StringFormat.GenericTypographic);if(measured.Width<=area.Width&&measured.Height<=area.Height)return font;font.Dispose();}return new Font(FontFamilyName,16F,style,GraphicsUnit.Point);}
}
